import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    # None represents an all-ones row.
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        child = dp[v]
        parent = dp[p]
        dp[v] = None
        if child is None:
            if parent is None:
                dp[p] = list(range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            s = 0
            if parent is None:
                for j in range(m):
                    s += child[j]
                    if s >= MOD:
                        s -= MOD
                    child[j] = s
                dp[p] = child
            else:
                for j in range(m):
                    s += child[j]
                    if s >= MOD:
                        s -= MOD
                    parent[j] = parent[j] * s % MOD
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        cur = i
        product = None
        # All values on a directed cycle must be equal.
        while deg[cur]:
            deg[cur] = 0
            row = dp[cur]
            if row is not None:
                if product is None:
                    product = row
                else:
                    for j in range(m):
                        product[j] = product[j] * row[j] % MOD
            cur = a[cur]
        total = m if product is None else sum(product) % MOD
        ans = ans * total % MOD
    print(ans)


if __name__ == '__main__':
    main()

