import sys
from math import gcd

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:], 1):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                factors.setdefault(p, []).append((i, e))
            p += 1
        if x > 1:
            factors.setdefault(x, []).append((i, 1))

    answer = 1
    for p, edges in factors.items():
        g = 0
        for _, e in edges:
            g = gcd(g, e)
        p = pow(p, g, MOD)
        edges = [(i, e // g) for i, e in edges]
        total = sum(e for _, e in edges)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * p % MOD

        # Heights are normalized so that their minimum so far is zero.
        dp = [1]
        last = 0
        for i, e in edges:
            gap = i - last - 1
            if gap:
                base = pow(p, gap, MOD)
                w = 1
                for h in range(len(dp)):
                    dp[h] = dp[h] * w % MOD
                    w = w * base % MOD

            nd = [0] * (len(dp) + e)
            step = pow(p, i, MOD)
            weights = [1] * (e + 1)
            for j in range(1, e + 1):
                weights[j] = weights[j - 1] * step % MOD

            for h, v in enumerate(dp):
                if not v:
                    continue
                nh = h + e
                nd[nh] = v * powers[nh] % MOD
                if h >= e:
                    nh = h - e
                    nd[nh] = (nd[nh] + v * powers[nh]) % MOD
                else:
                    # A new minimum shifts all i previous heights upward.
                    nd[0] = (nd[0] + v * weights[e - h]) % MOD
            dp = nd
            last = i

        gap = n - 1 - last
        if gap:
            base = pow(p, gap, MOD)
            w = 1
            for h in range(len(dp)):
                dp[h] = dp[h] * w % MOD
                w = w * base % MOD
        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    main()

