import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    n = len(a)
    maximum = max(a)
    phi = list(range(maximum + 1))
    for p in range(2, maximum + 1):
        if phi[p] == p:
            for j in range(p, maximum + 1, p):
                phi[j] -= phi[j] // p

    present = set(a)
    groups = {}
    for d in range(1, maximum + 1):
        key = tuple(x for x in range(d, maximum + 1, d) if x in present)
        if key:
            groups[key] = groups.get(key, 0) + phi[d]
    divisors = [None] * (maximum + 1)
    for x in present:
        divisors[x] = []
    for index, (key, weight) in enumerate(groups.items()):
        for x in key:
            divisors[x].append((index, weight))
    sums = [0] * len(groups)
    del groups, phi, present, data

    answer = 0
    power = 1
    out = []
    i = 0
    while i < n:
        x = a[i]
        end = i + 1
        while end < n and a[end] == x:
            end += 1
        length = end - i
        if length == 1:
            delta = power
        else:
            delta = power * (pow(2, length, MOD) - 1) % MOD
        contribution = 0
        for d, weight in divisors[x]:
            old = sums[d]
            contribution += weight * old
            sums[d] = old + delta
        if length == 1:
            answer = (answer * 2 + contribution) % MOD
            out.append(str(answer))
            power = power * 2 % MOD
        else:
            for _ in range(length):
                answer = (answer * 2 + contribution) % MOD
                out.append(str(answer))
                contribution += x * power
                power = power * 2 % MOD
        i = end
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

