from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # Make S the machine with the better cost per unit of capacity.
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        # Any larger number of T machines can be replaced by S machines.
        options = [(t * b, t * q) for t in range(a // gcd(a, b))]
        rows.append((a, p, options))

    def feasible(w):
        total = 0
        for a, p, options in rows:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                if capacity >= w:
                    if cost < best:
                        best = cost
                    break
                value = cost + ((w - capacity + a - 1) // a) * p
                if value < best:
                    best = value
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

