class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # steps[x] counts operations needed to reduce x to 1.
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = steps[x.bit_count()] + 1

        # dp[j] counts prefixes strictly smaller than s's prefix,
        # with exactly j set bits. The equal prefix is tracked separately.
        dp = [0] * (length + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            for ones in range(i + 1, 0, -1):
                dp[ones] = (dp[ones] + dp[ones - 1]) % MOD
            if bit == '1':
                dp[prefix_ones] = (dp[prefix_ones] + 1) % MOD
                prefix_ones += 1

        return sum(
            dp[ones]
            for ones in range(1, length + 1)
            if steps[ones] < k
        ) % MOD

