import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for k in range(m):
        u, v = data[2 + 2*k] - 1, data[3 + 2*k] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form of the adjacency matrix over GF(2).
    pivots = []
    r = 0
    for c in range(n):
        p = next((i for i in range(r, n) if (rows[i] >> c) & 1), -1)
        if p == -1:
            continue
        rows[r], rows[p] = rows[p], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    free_mask = (1 << n) - 1
    for c in pivots:
        free_mask ^= 1 << c

    # Use one distinct bit for each free variable. Each bit forms a
    # nullspace basis vector, so every neighbor XOR is zero.
    answer = [0] * n
    for c in range(n):
        if (free_mask >> c) & 1:
            answer[c] = 1 << c
    for i, c in enumerate(pivots):
        answer[c] = rows[i] & free_mask

    # A zero coordinate in every basis vector is necessarily zero in
    # every nullspace vector, making a positive label impossible.
    if any(x == 0 for x in answer):
        print('No')
    else:
        print('Yes')
        print(*answer)


if __name__ == '__main__':
    main()

