from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        answer = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            # Clockwise rotation in matrix coordinates.
            er, ec = dc, -dr
            suffix = [[1] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if er == 1 else range(n)
            for r in rows:
                nr = r + er
                if not 0 <= nr < n:
                    continue
                row, nextrow = grid[r], grid[nr]
                out, nxt = suffix[r], suffix[nr]
                for c in range(m):
                    nc = c + ec
                    if 0 <= nc < m:
                        wanted = 2 if row[c] == 1 else 2 - row[c]
                        if nextrow[nc] == wanted:
                            out[c] = 1 + nxt[nc]

            previous = [0] * m
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            for r in rows:
                current = [0] * m
                row = grid[r]
                pr = r - dr
                prevrow = grid[pr] if 0 <= pr < n else None
                for c in range(m):
                    if row[c] == 1:
                        length = 1
                    else:
                        pc = c - dc
                        if prevrow is None or not 0 <= pc < m or previous[pc] == 0:
                            continue
                        wanted = 2 if prevrow[pc] == 1 else 2 - prevrow[pc]
                        if row[c] != wanted:
                            continue
                        length = previous[pc] + 1
                    current[c] = length
                    candidate = length + suffix[r][c] - 1
                    if candidate > answer:
                        answer = candidate
                previous = current
        return answer

