 def countNonDecreasingSubarrays(self, nums, k):
  blocks=deque();right=len(nums)-1;cost=0;answer=0
  for left in range(len(nums)-1,-1,-1):
   value=nums[left]
   while blocks and nums[blocks[0]]<=value:
    start=blocks.popleft();end=blocks[0] if blocks else right+1
