class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        answer = len(s)
        for target in range(1, max(counts) + 1):
            dp = [0] * 28
            for i in range(25, -1, -1):
                c = counts[i]
                best = min(c, abs(c - target)) + dp[i + 1]
                if i < 25 and counts[i + 1] < target:
                    deficit = target - counts[i + 1]
                    # Either remove this letter altogether or retain target
                    # copies, converting surplus copies into the next letter.
                    pair = min(
                        c - min(c, deficit),
                        abs(c - target) - min(max(c - target, 0), deficit)
                    )
                    best = min(best, pair + deficit + dp[i + 2])
                dp[i] = best
            answer = min(answer, dp[0])
            if answer == 0:
                return 0
        return answer

