def fwht(a):
    n=len(a); step=1
    while step<n:
        jump=step*2
        for start in range(0,n,jump):
            for i in range(start,start+step):
                x=a[i]; y=a[i+step]
                a[i]=x+y; a[i+step]=x-y
        step=jump

