            coeff=sum((-1)**j*comb(k,j)*comb(d-k,t-j) for j in range(max(0,t-(d-k)),min(k,t)+1))
            value+=coeff*min(t,w-t)
        eigen.append(value)
    fwht(a)
    for i in range(n): a[i]*=eigen[i.bit_count()]
    fwht(a)
    return min(a)//n
