import sys

MOD = 998244353


def solve_case(h, w, grid):
    col = bytearray(w)
    for row in grid:
        if row.count(b'A') & 1:
            return 0
        for j, c in enumerate(row):
            if c == 65:
                col[j] ^= 1
    if any(col):
        return 0

    n = h + w
    parent = [-1] * n
    parity = bytearray(n)

    def find(x):
        value = 0
        while parent[x] >= 0:
            p = parent[x]
            if parent[p] >= 0:
                parity[x] ^= parity[p]
                parent[x] = parent[p]
            value ^= parity[x]
            x = parent[x]
        return x, value

    components = n
    for i, row in enumerate(grid):
        horizontal = 0
        for j, c in enumerate(row):
            if c == 65:
                horizontal ^= 1
                col[j] ^= 1
            else:
                a, x = find(i)
                b, y = find(h + j)
                d = horizontal ^ col[j] ^ 1 ^ x ^ y
                if a == b:
                    if d:
                        return 0
                else:
                    if parent[a] > parent[b]:
                        a, b = b, a
                    parent[a] += parent[b]
                    parent[b] = a
                    parity[b] = d
                    components -= 1
    return pow(2, components, MOD)


def main():
    inp = sys.stdin.buffer
    t = int(inp.readline())
    ans = []
    for _ in range(t):
        h, w = map(int, inp.readline().split())
        grid = [inp.readline().strip() for _ in range(h)]
        ans.append(str(solve_case(h, w, grid)))
    sys.stdout.write('\n'.join(ans))


if __name__ == '__main__':
    main()

